# Dot-sourced by the other scripts; not meant to be run directly.

# Where `mb update` downloads from (override with MB_CLONER_URL)
$mb_base_url = if ($env:MB_CLONER_URL) { $env:MB_CLONER_URL } else { 'https://raw.githubusercontent.com/lucas-zimerman/multibranch-cloner/main' }

$mb_lib = $PSScriptRoot

# terminal.ps1 sets the tab title; data.ps1 and env.local.ps1 are generated by install.ps1
. (Join-Path $mb_lib 'windows\terminal.ps1')
if (Test-Path (Join-Path $mb_lib 'data.ps1'))      { . (Join-Path $mb_lib 'data.ps1') }
if (Test-Path (Join-Path $mb_lib 'env.local.ps1')) { . (Join-Path $mb_lib 'env.local.ps1') }

# Sets the terminal tab title for the given folder.
function Set-Tab([string]$Folder) {
  Set-TerminalTabHeader "$tab_title_prefix $Folder - $agent_name"
}

# Runs git and fails when it exits non-zero.
function Invoke-Git {
  & git @args
  if ($LASTEXITCODE -ne 0) { throw "git $($args -join ' ') failed (exit $LASTEXITCODE)" }
}

# Returns one object per clone: Last (DateTime), Dir, Branch, Pr (number or '-'), State (or '-').
function Get-Clones {
  # Clones live at most 3 folders deep (e.g. lz/fix/foo), so their .git is at depth 4.
  # Walks manually so it never descends into .git itself or into .mb-cloner.
  $found = [System.Collections.Generic.List[string]]::new()
  function Find-Git([string]$Path, [int]$Depth) {
    foreach ($item in Get-ChildItem -LiteralPath $Path -Force -ErrorAction SilentlyContinue) {
      if ($item.Name -eq '.git') {
        # The folder holding mb itself is not a clone
        if ($Depth -gt 1) { $found.Add($item.FullName) }
        continue
      }
      if ($item.PSIsContainer -and $Depth -lt 4 -and $item.Name -ne '.mb-cloner') {
        Find-Git $item.FullName ($Depth + 1)
      }
    }
  }
  $base = (Get-Location).Path
  Find-Git $base 1

  foreach ($gitdir in $found) {
    $dir = Split-Path -Parent $gitdir
    $branch = (& git -C $dir branch --show-current) -join ''
    if (-not $branch) { $branch = '(detached)' }

    # .git/index is touched by checkout/add/commit/status, so it tracks the last time the clone was used
    $index = Join-Path $gitdir 'index'
    if (Test-Path -LiteralPath $index) {
      $last = (Get-Item -LiteralPath $index -Force).LastWriteTime
    } else {
      try { $last = [DateTimeOffset]::FromUnixTimeSeconds([long](& git -C $dir log -1 --format=%ct 2>$null)).LocalDateTime }
      catch { $last = [DateTime]::MinValue }
    }

    $pr = '-'; $state = '-'
    # gh may be missing or logged out: keep going with "-" instead of aborting
    try {
      $out = & gh pr list --repo $repo --head $branch --state all --limit 1 --json number,state 2>$null
      if ($LASTEXITCODE -eq 0 -and $out) {
        $first = @($out | ConvertFrom-Json) | Select-Object -First 1
        if ($first) { $pr = [string]$first.number; $state = ([string]$first.state).ToLower() }
      }
    } catch { }

    $rel = $dir.Substring($base.Length).TrimStart('\', '/')
    [pscustomobject]@{ Last = $last; Dir = ".\$rel"; Branch = $branch; Pr = $pr; State = $state }
  }
}
